define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_100.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e327927","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_98.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e328031","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_89.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e328135","topics":[]},{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_35.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e328239","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_33.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e328343","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_31.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e328447","topics":[]},{"title":"Removing the magnet service access vent","shortdesc":"<p class=\"shortdesc\">Removes the service access vent from the magnet enclosure allowing a ladder to stand close to the magnet on the left-hand side.<\/p>","href":"t_RemovingTheServiceAccessVent_22.html","attributes":{"data-id":"id_2002970"},"menu":{"hasChildren":false},"tocID":"id_2002970-d46e328551","topics":[]},{"title":"Removing the table interface assembly","shortdesc":"<p class=\"shortdesc\">Remove the table interface (TIF) assembly from the magnet outer electronics.<\/p>","href":"t_RemovingTheTableInterfaceAssembly.html","attributes":{"data-id":"id_2021391"},"menu":{"hasChildren":false},"tocID":"id_2021391-d46e328655","topics":[]},{"title":"Installing the table interface assembly","shortdesc":"<p class=\"shortdesc\">Install a table interface (TIF) assembly in the magnet outer electronics.<\/p>","href":"t_InstallingTheTIF.html","attributes":{"data-id":"id_2012259"},"menu":{"hasChildren":false},"tocID":"id_2012259-d46e328759","topics":[]},{"title":"Installing the magnet service access vent","shortdesc":"<p class=\"shortdesc\">Installs the service access vent onto the magnet enclosure.<\/p>","href":"t_InstallingTheServiceAccessVent_21.html","attributes":{"data-id":"id_2002971"},"menu":{"hasChildren":false},"tocID":"id_2002971-d46e328863","topics":[]},{"title":"Installing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Installs the rear service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheRearServiceAccessPanel_30.html","attributes":{"data-id":"id_2002967"},"menu":{"hasChildren":false},"tocID":"id_2002967-d46e328968","topics":[]},{"title":"Installing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Installs the front service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheFrontServiceAccessPanel_32.html","attributes":{"data-id":"id_2002825"},"menu":{"hasChildren":false},"tocID":"id_2002825-d46e329072","topics":[]},{"title":"Installing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Installs the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_InstallingTheServiceAccessTrim_34.html","attributes":{"data-id":"id_2002822"},"menu":{"hasChildren":false},"tocID":"id_2002822-d46e329176","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_91.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e329280","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_96.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e329384","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_115.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e329488","topics":[]}]});